/* one character cell with its background; glyph: CP437 code 0-255 */
static inline void nzf_cell(const struct nzf_font *f, int x, int y, unsigned glyph, uint16_t fg, uint16_t bg)
{
	const unsigned char *g = f->data + (glyph & 255) * f->h;
	if (x < 0 || y < 0 || x + f->w > nzui_w || y + f->h > nzui_h) return;
	for (int j = 0; j < f->h; j++) {
		uint16_t *p = nzui_fb + (y + j) * nzui_w + x; unsigned b = g[j];
		for (int i = 0; i < f->w; i++) p[i] = (b << i & 0x80) ? fg : bg;
	}
}
/* text without a background; bytes are CP437 codes (ASCII is the same) */
static inline void nzf_text(const struct nzf_font *f, int x, int y, uint16_t fg, const char *s, int maxch)
{
	for (const unsigned char *p = (const unsigned char *)s; *p && maxch-- > 0; p++, x += f->w) {
		const unsigned char *g = f->data + *p * f->h;
		if (x < 0 || y < 0 || x + f->w > nzui_w || y + f->h > nzui_h) continue;
		for (int j = 0; j < f->h; j++)
			for (int i = 0; i < f->w; i++) if (g[j] << i & 0x80) nzui_fb[(y + j) * nzui_w + x + i] = fg;
	}
}
